#![forbid(unsafe_code)]
//! Generates seat-aware device rules so the Wayland session gets access to
//! render nodes, backlight, sensors and board-specific memory devices.

use crate::board_db::match_board;
use crate::HardwareReport;

/// Build the udev rules content for the running machine.
pub fn generate(report: &HardwareReport) -> String {
    let board = match_board(report);
    let mut rules = String::from(
        "# Generated by namikaze-hal. Do not edit.\n\
         KERNEL==\"render*\",        TAG+=\"uaccess\"\n\
         SUBSYSTEM==\"drm\",         TAG+=\"uaccess\"\n\
         SUBSYSTEM==\"backlight\",   TAG+=\"uaccess\"\n\
         SUBSYSTEM==\"iio\",         TAG+=\"uaccess\"\n\
         SUBSYSTEM==\"dma_heap\",    GROUP=\"video\", MODE=\"0660\"\n\
         KERNEL==\"gpiochip*\",      GROUP=\"gpio\",  MODE=\"0660\"\n",
    );
    match board.id {
        "rpi5" | "rpi4" | "rpi3" | "rpi-zero-2-w" => rules.push_str(
            "KERNEL==\"vcio\",          GROUP=\"video\", MODE=\"0660\"\n\
             KERNEL==\"gpiomem\",       GROUP=\"gpio\",  MODE=\"0660\"\n",
        ),
        "rock-5b" | "orangepi-5" | "rock-3a" => {
            rules.push_str("KERNEL==\"mali*\",         GROUP=\"video\", MODE=\"0660\"\n")
        }
        _ => {}
    }
    rules
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Arch;

    #[test]
    fn base_rules_always_present() {
        let r = HardwareReport { arch: Some(Arch::X86_64), ..Default::default() };
        let s = generate(&r);
        assert!(s.contains("render*"));
        assert!(s.contains("uaccess"));
    }

    #[test]
    fn rpi_gets_gpiomem_rule() {
        let r = HardwareReport {
            arch: Some(Arch::Aarch64),
            dt_compatibles: vec!["raspberrypi,4-model-b".to_string()],
            ..Default::default()
        };
        assert!(generate(&r).contains("gpiomem"));
    }
}
